<?php $title='Privacy Assessments'; ?>
<div class="container py-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><div class="text-muted small"><?=e($client['company_name'])?></div><h1 class="h3 mb-0">Privacy assessments</h1></div><a class="btn btn-primary" href="<?=url('assessments/create',['client_id'=>(int)$client['id']])?>">New assessment</a></div><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Title</th><th>Type</th><th>Status</th><th>Risk</th><th>Due</th><th>Owner</th><th></th></tr></thead><tbody><?php foreach($assessments as $a):?><tr><td class="fw-semibold"><?=e($a['title'])?></td><td><?=e(ucwords(str_replace('_',' ',$a['assessment_type'])))?></td><td><?=e(ucwords(str_replace('_',' ',$a['status'])))?></td><td><?=e((string)($a['risk_score']??'—'))?><?php if($a['risk_score']!==null):?>/100<?php endif;?></td><td><?=e($a['due_date']??'—')?></td><td><?=e($a['owner_name']??'—')?></td><td><a class="btn btn-sm btn-outline-secondary" href="<?=url('assessments/edit',['id'=>(int)$a['id'],'client_id'=>(int)$client['id']])?>">Edit</a></td></tr><?php endforeach;?><?php if(!$assessments):?><tr><td colspan="7" class="text-center text-muted py-5">No assessments yet.</td></tr><?php endif;?></tbody></table></div></div></div>
